insert into "institutions" ("id", "name", "type", "category", "ownership", "operational_status", "website", "email", "phone", "logo_url", "location", "town", "county", "region", "research_data", "validation", "sources", "research_score", "research_status", "created_at", "updated_at", "sync_status", "sync_updated_at", "sync_run_id", "conflict", "verification_status", "verified_at", "verified_by_run", "claimed_by", "claimed_until", "claim_queue", "attempt_count", "last_error", "last_writer", "duplicate_of", "registration_status", "profile_level", "research_note", "research_queued_at", "research_origin", "research_pass", "verification_pass", "conflict_pass", "verification_basis", "estimated_student_count", "has_elearning", "has_distance_learning", "has_teaching_courses", "campuses", "affiliation", "about", "description", "facilities", "accreditations", "courses", "personal_contacts", "health_score", "verified_fields_jsonb", "changelog_jsonb", "last_sync_at", "target_fields", "social_media", "corpus_sources", "institution_sources", "other_sources", "geo", "prefetch_status", "evidence_prefetched_at", "evidence_packaged_at", "prefetch_error") overriding system value values ('dfc0815b-3ead-47d6-a3c4-a94d32ba8b06', 'A.i.c Diguna Rainbow Polytechnic', 'TVET', 'VTC', 'private', 'active', 'https://diguna.de/vocational-school/', 'rainbow-polytechnic@diguna.de', '0736-231198', null, 'Lambuiywo Market Off Kupere-Timboroa Road', 'Songhor', 'Nandi County', 'Rift Valley', '{"context":{"about":"A.I.C Diguna Rainbow Polytechnic is a faith-based private vocational training college in the Tinderet sub-county of Nandi County, founded in 2002 and run under the DIGUNA mission, training artisans in masonry, welding, carpentry, electrical, plumbing and garment trades.","courses":[{"name":"Hair Dressing and Beauty","level":"Artisan","exam_body":"NITA"},{"name":"Electrical Installation","level":"Artisan","exam_body":"NITA"},{"name":"Dressmaking","level":"Artisan","exam_body":"NITA"},{"name":"Carpentry and Joinery","level":"Artisan","exam_body":"NITA"},{"name":"Masonry","level":"Artisan","exam_body":"NITA"},{"name":"Welding and Fabrication","level":"Artisan","exam_body":"NITA"},{"name":"Plumbing","level":"Artisan","exam_body":"NITA"},{"name":"Information Communication Technology (ICT)","level":"Certificate","exam_body":"KASNEB"}],"sources":{"courses":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/VTC/0006/2016","description":"https://diguna.de/vocational-school/"},"facilities":["Library (under construction)","Renewable energy projects (PV solar and hot water)"],"description":"A.I.C Diguna Rainbow Polytechnic is a faith-based applied technology training institution founded in 2002 in the Tinderet sub-district of Nandi County, run as part of the DIGUNA mission and reporting more than 2000 technicians trained. The Technical and Vocational Education and Training Authority registers it as TVETA/PRIVATE/VTC/0006/2016, registered on 3 June 2016 with a licence valid to 13 July 2028 and the status ''Registered and Licensed''. Its accredited table lists ten programmes: nine NITA trade tests in carpentry and joinery, electrical wireman, hairdressing, masonry, plumbing and pipe fitting, tailoring, welding and fabrication, dressmaking and beauty therapy, plus a KASNEB craft award in information communication technology. The DIGUNA vocational-school page states that its courses are TVETA-accredited in masonry, apparel manufacturing, welding and fabrication, carpentry and joinery, electrical, plumbing and barbering, and describes renewable-energy projects in PV solar and hot water plus a library under construction. All listed awards are artisan-level trade tests or a craft certificate, which correspond to the schema''s Artisan and Certificate levels.","accreditations":["TVETA registration TVETA/PRIVATE/VTC/0006/2016, registered 2016-06-03, licence valid to 2028-07-13, status ''Registered and Licensed''","NITA - examining body for the trade test programmes","KASNEB - examining body for the craft information communication technology programme"]},"basic_info":{"email":"rainbow-polytechnic@diguna.de","phone":"0736-231198","sources":{"website":"https://diguna.de/vocational-school/"},"website":"https://diguna.de/vocational-school/","location":{"town":"Songhor","county":"Nandi County","region":"Rift Valley","location":"Lambuiywo Market Off Kupere-Timboroa Road"},"logo_url":null},"personal_contacts":[],"institution_profile":{"type":"TVET","campuses":[],"category":"VTC","ownership":"private","has_elearning":["none","The DIGUNA vocational-school page publishes no learning-management portal or student login."],"has_teaching_courses":[false],"has_distance_learning":["none","The DIGUNA vocational-school page describes only on-campus practical trades training and publishes no distance or open-learning provision."],"estimated_student_count":null}}', '{"context.courses":{"status":"confirmed","rationale":"Register table lists nine NITA trade tests (carpentry and joinery, electrical wireman, hairdressing, masonry, plumbing and pipe fitting, tailoring, welding and fabrication, dressmaking, beauty therapy) and one KASNEB craft ICT award; the page corroborates masonry, apparel manufacturing, welding and fabrication, carpentry and joinery, electrical, plumbing and barbering. Stored composite ''Trade Test / Certificate'' levels were fixed to Artisan or Certificate per the register.","url_checked":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/VTC/0006/2016"},"basic_info.website":{"status":"confirmed","rationale":"The stored URL diguna.de/vocational-school/ returns the DIGUNA ''Vocational school in Tinderet'' page describing AIC DIGUNA Rainbow Vocational School, founded 2002.","url_checked":"https://diguna.de/vocational-school/"},"context.accreditations":{"status":"confirmed","rationale":"The page states its courses are accredited by the Technical and Vocational Education Training Authority; the register entry TVETA/PRIVATE/VTC/0006/2016 is Registered and Licensed to 2028-07-13 with NITA and KASNEB named as exam bodies.","url_checked":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/VTC/0006/2016"},"basic_info.location.county":{"status":"confirmed","rationale":"The DIGUNA vocational-school page places the school ''in the district of Nandi in the sub-district of Tinderet'', and the TVETA register row for TVETA/PRIVATE/VTC/0006/2016 records County Nandi.","url_checked":"https://diguna.de/vocational-school/"}}', '{"website":"https://diguna.de/vocational-school/"}', 69, 'researched', '2026-10-24 09:16:03.56084+00', '2026-11-20 17:55:31.495077+00', 'not_applied', '2026-10-30 07:02:58.225471+00', 'rebuild-flagged-05-t_56f62ab0', '[]', 'unverified', null, null, null, null, null, 0, null, 'verification', null, null, 'enriched', 'Requeued to re_research afresh under the new process', null, 're_research', 1, 0, 0, null, null, '["none","The DIGUNA vocational-school page publishes no learning-management portal or student login."]', '["none","The DIGUNA vocational-school page describes only on-campus practical trades training and publishes no distance or open-learning provision."]', '[false]', '[]', null, 'A.I.C Diguna Rainbow Polytechnic is a faith-based private vocational training college in the Tinderet sub-county of Nandi County, founded in 2002 and run under the DIGUNA mission, training artisans in masonry, welding, carpentry, electrical, plumbing and garment trades.', 'A.I.C Diguna Rainbow Polytechnic is a faith-based applied technology training institution founded in 2002 in the Tinderet sub-district of Nandi County, run as part of the DIGUNA mission and reporting more than 2000 technicians trained. The Technical and Vocational Education and Training Authority registers it as TVETA/PRIVATE/VTC/0006/2016, registered on 3 June 2016 with a licence valid to 13 July 2028 and the status ''Registered and Licensed''. Its accredited table lists ten programmes: nine NITA trade tests in carpentry and joinery, electrical wireman, hairdressing, masonry, plumbing and pipe fitting, tailoring, welding and fabrication, dressmaking and beauty therapy, plus a KASNEB craft award in information communication technology. The DIGUNA vocational-school page states that its courses are TVETA-accredited in masonry, apparel manufacturing, welding and fabrication, carpentry and joinery, electrical, plumbing and barbering, and describes renewable-energy projects in PV solar and hot water plus a library under construction. All listed awards are artisan-level trade tests or a craft certificate, which correspond to the schema''s Artisan and Certificate levels.', '["Library (under construction)","Renewable energy projects (PV solar and hot water)"]', '["TVETA registration TVETA/PRIVATE/VTC/0006/2016, registered 2016-06-03, licence valid to 2028-07-13, status ''Registered and Licensed''","NITA - examining body for the trade test programmes","KASNEB - examining body for the craft information communication technology programme"]', '[{"name":"Hair Dressing and Beauty","level":"Artisan","exam_body":"NITA"},{"name":"Electrical Installation","level":"Artisan","exam_body":"NITA"},{"name":"Dressmaking","level":"Artisan","exam_body":"NITA"},{"name":"Carpentry and Joinery","level":"Artisan","exam_body":"NITA"},{"name":"Masonry","level":"Artisan","exam_body":"NITA"},{"name":"Welding and Fabrication","level":"Artisan","exam_body":"NITA"},{"name":"Plumbing","level":"Artisan","exam_body":"NITA"},{"name":"Information Communication Technology (ICT)","level":"Certificate","exam_body":"KASNEB"}]', '[]', 66, '{}', '[]', null, '', '[]', '[]', '[]', '[]', '{}', 'pending', null, null, null);
