UBLIC/VTC/0016/2019, registered 2019-01-14, licence valid to 2029-07-02, status ''Registered and Licensed''","NITA trade testing for arc welding and masonry"],"old_val":null,"timestamp":"2026-11-17T01:40:10.471844+00:00","decided_by":"agent:t_debf294e"},{"field":"courses","action":"gap_sync","new_val":[{"name":"Arc Welding","level":"Artisan","exam_body":"NITA"},{"name":"Masonry","level":"Artisan","exam_body":"NITA"}],"old_val":null,"timestamp":"2026-11-17T01:40:10.471844+00:00","decided_by":"agent:t_debf294e"}]', '2026-11-17 01:40:10.462126+00', '', '[]', '[]', '[]', '[]', '{}', 'pending', null, null, null);
