insert into "institutions" ("id", "name", "type", "category", "ownership", "operational_status", "website", "email", "phone", "logo_url", "location", "town", "county", "region", "research_data", "validation", "sources", "research_score", "research_status", "created_at", "updated_at", "sync_status", "sync_updated_at", "sync_run_id", "conflict", "verification_status", "verified_at", "verified_by_run", "claimed_by", "claimed_until", "claim_queue", "attempt_count", "last_error", "last_writer", "duplicate_of", "registration_status", "profile_level", "research_note", "research_queued_at", "research_origin", "research_pass", "verification_pass", "conflict_pass", "verification_basis", "estimated_student_count", "has_elearning", "has_distance_learning", "has_teaching_courses", "campuses", "affiliation", "about", "description", "facilities", "accreditations", "courses", "personal_contacts", "health_score", "verified_fields_jsonb", "changelog_jsonb", "last_sync_at", "target_fields", "social_media", "corpus_sources", "institution_sources", "other_sources", "geo", "prefetch_status", "evidence_prefetched_at", "evidence_packaged_at", "prefetch_error") overriding system value values ('bec71d83-04da-42d3-ba56-d0b7f26cb9fa', 'Afiagate Training Centre', 'TVET', 'TVC', 'private', 'active', 'https://www.afiagate.com/', null, '0748 595034', null, 'Krishna Center, 7th Floor Suite 700, Westlands, Nairobi, 00100', 'Nairobi', 'Nairobi County', 'Nairobi', '{"context":{"about":"Afiagate Training Centre, trading publicly as AfiaGate College and also seen online as Afiagate Medical College, is a private TVET institution in Nairobi registered with TVETA as TVETA/PRIVATE/TVC/0055/2025. It trains healthcare providers in community health, nursing and caregiving programmes and positions itself as a route to healthcare job markets abroad, including European markets.","courses":[{"name":"Community Health","level":"Certificate","exam_body":"TVET CDACC"}],"sources":{"about":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025","https://www.afiagate.com/"],"courses":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025"],"facilities":[],"description":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025","https://www.afiagate.com/","https://www.zoominfo.com/pic/afiagate/1315511536","https://www.facebook.com/Afiagate/videos/922474275933296/"],"accreditations":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025"]},"facilities":null,"description":"Afiagate Training Centre is a private TVET institution recorded in the TVETA register of accredited TVET institutions as TVETA/PRIVATE/TVC/0055/2025, registered on 25 April 2025 with the licence valid to 24 April 2030 and the status Registered and Licensed. The regulator publishes one accredited award, community health at level 4 under the TVET CDACC competency-based curriculum, normalised here at certificate level. The centre operates from Krishna Center, 7th Floor Suite 700, Westlands, Nairobi, and trades publicly as AfiaGate College, describing itself as a nursing and caregiving education provider with over 500 students and a focus on preparing healthcare providers for job markets abroad, including specialised preparation for European healthcare markets. Its own Facebook video recruitment (''Certified Nurse Assistant at Afiagate training Centre. February Intake ongoing'') confirms active intakes beyond the single TVETA-listed award, and a ZoomInfo profile independently describes accredited certificates and diplomas in community health nursing and healthcare assistance. The institution''s domain www.afiagate.com currently serves unrelated third-party spam content (an apparent domain compromise), so on-site contact details such as e-mail could not be extracted and remain null rather than guessed.","accreditations":["Technical and Vocational Education and Training Authority (TVETA) registration TVETA/PRIVATE/TVC/0055/2025, registered 2025-04-25, licence valid to 2030-04-24, status ''Registered and Licensed''","TVET Curriculum Development, Assessment and Certification Council (CDACC) - examining body for the accredited community health award"]},"basic_info":{"email":null,"phone":"+254748595034","sources":{"email":[],"phone":["https://maps.google.com/?cid=435438936591813804&g_mp=Cidnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLlNlYXJjaFRleHRQAhgEIAA"],"website":["https://www.afiagate.com/","https://www.zoominfo.com/pic/afiagate/1315511536"],"logo_url":[],"location.town":["https://maps.google.com/?cid=435438936591813804&g_mp=Cidnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLlNlYXJjaFRleHRQAhgEIAA"],"location.county":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025"],"location.region":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025"],"location.location":["https://www.afiagate.com/","https://maps.google.com/?cid=435438936591813804&g_mp=Cidnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLlNlYXJjaFRleHRQAhgEIAA"]},"website":"https://www.afiagate.com/","location":{"town":"Nairobi","county":"Nairobi County","region":"Nairobi","location":"Krishna Center, 7th Floor Suite 700, Westlands, Nairobi, 00100"},"logo_url":null},"personal_contacts":[],"institution_profile":{"type":"TVET","sources":{"type":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025"],"campuses":["https://www.afiagate.com/","https://maps.google.com/?cid=435438936591813804&g_mp=Cidnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLlNlYXJjaFRleHRQAhgEIAA"],"category":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025"],"ownership":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025"],"affiliation":[],"has_elearning":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055/2025"],"has_teaching_courses":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0055