insert into "institutions" ("id", "name", "type", "category", "ownership", "operational_status", "website", "email", "phone", "logo_url", "location", "town", "county", "region", "research_data", "validation", "sources", "research_score", "research_status", "created_at", "updated_at", "sync_status", "sync_updated_at", "sync_run_id", "conflict", "verification_status", "verified_at", "verified_by_run", "claimed_by", "claimed_until", "claim_queue", "attempt_count", "last_error", "last_writer", "duplicate_of", "registration_status", "profile_level", "research_note", "research_queued_at", "research_origin", "research_pass", "verification_pass", "conflict_pass", "verification_basis", "estimated_student_count", "has_elearning", "has_distance_learning", "has_teaching_courses", "campuses", "affiliation", "about", "description", "facilities", "accreditations", "courses", "personal_contacts", "health_score", "verified_fields_jsonb", "changelog_jsonb", "last_sync_at", "target_fields", "social_media", "corpus_sources", "institution_sources", "other_sources", "geo", "prefetch_status", "evidence_prefetched_at", "evidence_packaged_at", "prefetch_error") overriding system value values ('0058814a-06a3-4f6d-b9a6-b59286f9036e', 'Africa Institute of Health and Development', 'TVET', 'TVC', 'private', 'active', 'https://www.aihd.ac.ke/', 'info@aihd.ac.ke', '0721 421615', null, 'Kinanie Shopping Center, Athi River', 'Athi River', 'Machakos County', 'Eastern', '{"context":{"about":"Africa Institute of Health and Development is a private technical and vocational college at Kinanie Shopping Center in Athi River, Machakos County, Kenya. It is registered and licensed by the Technical and Vocational Education and Training Authority as TVETA/PRIVATE/TVC/0164/2016 and trains health, community development, business and social work professionals at KNEC craft and diploma level and at CDACC competency-based levels.","courses":[{"name":"Social Development","level":"Certificate","exam_body":"KNEC"},{"name":"Banking and Finance","level":"Diploma","exam_body":"KNEC"},{"name":"Business Management","level":"Diploma","exam_body":"KNEC"},{"name":"Social Work and Community Development","level":"Diploma","exam_body":"KNEC"},{"name":"Supply Chain Management","level":"Diploma","exam_body":"KNEC"},{"name":"Tourism Management","level":"Diploma","exam_body":"KNEC"},{"name":"Community Health Level 4","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Home Care Management Level 4","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Accommodation Operations Level 4","level":"Artisan","exam_body":"TVET CDACC"}],"sources":{"about":"https://www.aihd.ac.ke/","courses":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0164/2016","facilities":"https://www.aihd.ac.ke/","description":"https://www.aihd.ac.ke/","accreditations":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0164/2016"},"facilities":[],"description":"The Africa Institute of Health and Development (AIHD) is a private technical and vocational college operating from Kinanie Shopping Center on the Athi River side of Machakos County, registered by the Technical and Vocational Education and Training Authority under registration number TVETA/PRIVATE/TVC/0164/2016, with a licence valid to 2 July 2029. The institute describes itself as a health and development training provider registered with the Directorate of Industrial Training, the Ministry of Education and TVETA, and lists KNEC, KASNEB, ABMA, ICM and ABE as its examination bodies. The TVETA register of accredited programmes records fourteen qualifications, including KNEC craft and diploma programmes in business management, social development, banking and finance, social work and community development, supply chain management and tourism management, plus CDACC Level 4 competency-based programmes in community health, home care management and accommodation operations. Its own prospectus additionally advertises a long list of specialist diplomas in community based health, conflict and disaster management, guidance and counselling, occupational health and safety, project planning and management, and health and physiotherapy, which are not all reflected in the regulator''s accredited list. The institute publishes the telephone lines 0721 421615 and 0721 318501 and the email address info@aihd.ac.ke. Note that the source database records this institution under a Nairobi town address, whereas both the regulator and the institution''s own website place it in Machakos County at Athi River.","accreditations":["TVETA registration TVETA/PRIVATE/TVC/0164/2016, registered 2016-07-14, licence valid to 2029-07-02, status ''Registered and Licensed''","KNEC examination for the listed craft and diploma programmes","TVET CDACC assessment for the listed competency-based level programmes"]},"basic_info":{"email":"info@aihd.ac.ke","phone":"0721 421615","sources":{"town":"https://www.aihd.ac.ke/","email":"https://www.aihd.ac.ke/","phone":"https://www.aihd.ac.ke/","county":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0164/2016","region":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0164/2016","website":"https://www.aihd.ac.ke/","location":"https://www.aihd.ac.ke/"},"website":"https://www.aihd.ac.ke/","location":{"town":"Athi River","county":"Machakos County","region":"Eastern","location":"Kinanie Shopping Center, Athi River"},"logo_url":null},"personal_contacts":[],"institution_profile":{"type":"TVET","sources":{"type":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0164/2016","campuses":"https://www.aihd.ac.ke/","category":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0164/2016","ownership":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0164/2016","has_elearning":"https://www.aihd.ac.ke/","has_teaching_courses":"https://www.aihd.ac.ke/","has_distance_learning":"https://www.aihd.ac.ke/"},"