insert into "institutions" ("id", "name", "type", "category", "ownership", "operational_status", "website", "email", "phone", "logo_url", "location", "town", "county", "region", "research_data", "validation", "sources", "research_score", "research_status", "created_at", "updated_at", "sync_status", "sync_updated_at", "sync_run_id", "conflict", "verification_status", "verified_at", "verified_by_run", "claimed_by", "claimed_until", "claim_queue", "attempt_count", "last_error", "last_writer", "duplicate_of", "registration_status", "profile_level", "research_note", "research_queued_at", "research_origin", "research_pass", "verification_pass", "conflict_pass", "verification_basis", "estimated_student_count", "has_elearning", "has_distance_learning", "has_teaching_courses", "campuses", "affiliation", "about", "description", "facilities", "accreditations", "courses", "personal_contacts", "health_score", "verified_fields_jsonb", "changelog_jsonb", "last_sync_at", "target_fields", "social_media", "corpus_sources", "institution_sources", "other_sources", "geo", "prefetch_status", "evidence_prefetched_at", "evidence_packaged_at", "prefetch_error") overriding system value values ('9ee50a15-f100-4ebb-b0bc-983fde39b984', 'African Institute of Research and Development Studies - Bungoma Campus', 'TVET', 'TVC', 'private', 'active', 'https://www.airads.ac.ke/', 'info@airads.ac.ke', '0715 771316', 'https://portal.airads.ac.ke/TenantCustomization/GetLogo?tenantId=1154&v1=639307360825094079', 'College Plaza, 3rd Floor, opposite Main Stage, Bungoma Town', 'Bungoma', 'Bungoma County', 'Western', '{"context":{"about":"African Institute of Research and Development Studies - Bungoma Campus is a private technical and vocational college campus in Bungoma County, Western region, Kenya, registered and licensed by the Technical and Vocational Education and Training Authority as TVETA/PRIVATE/TVC/0088/2016 and accredited for KASNEB and KNEC business, accountancy, human resource, information technology, social development and supply chain programmes at craft and diploma levels. The campus operates from College Plaza, 3rd Floor, opposite Main Stage, Bungoma Town, and belongs to the AIRADS College network of campuses.","courses":[{"name":"Information Communication Technology (Craft, KASNEB)","level":"Certificate","exam_body":"KASNEB"},{"name":"Accounting Technicians Diploma","level":"Diploma","exam_body":"KASNEB"},{"name":"Accountancy (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Business Management (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Social Development (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Human Resource Management (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Information Communication Technology (Craft, KNEC)","level":"Certificate","exam_body":"KNEC"},{"name":"Supply Chain Management (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Business Management (Diploma)","level":"Diploma","exam_body":"KNEC"},{"name":"Human Resource Management (Diploma)","level":"Diploma","exam_body":"KNEC"}],"sources":{"about":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0088/2016","https://www.airads.ac.ke/contact/"],"courses":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0088/2016"],"description":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0088/2016","https://www.airads.ac.ke/contact/","https://studyinkenya.co.ke/campus/african-institute-of-research-and-development-studies/bungoma-town-campus","https://portal.airads.ac.ke/Home/Login?v1=639307360825094079"],"accreditations":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0088/2016"]},"facilities":null,"description":"The African Institute of Research and Development Studies - Bungoma Campus is the Bungoma Town campus of AIRADS College, a private technical and vocational college registered by the Technical and Vocational Education and Training Authority under registration number TVETA/PRIVATE/TVC/0088/2016, registered on 14 April 2016 with a licence valid to 2 July 2029 in the Registered and Licensed status. The register''s accredited programme records for the campus list eleven course rows covering the KASNEB craft Information Communication Technology award and the Accounting Technicians Diploma alongside a KASNEB Certified Public Accountants professional stream, and KNEC-examined craft certificates and diplomas in accountancy, business management, human resource management, information communication technology, social development and supply chain management. The campus operates from College Plaza, 3rd Floor, opposite Main Stage in Bungoma Town, and the AIRADS College network lists Bungoma Town alongside Eldoret, Nairobi, Kericho, Kisumu, Nakuru and Mombasa campus locations. Contact is maintained on 0715 771316, and the college runs a student portal at portal.airads.ac.ke; no dedicated e-learning platform or distance-learning provision is published for the campus.","accreditations":["TVETA registration TVETA/PRIVATE/TVC/0088/2016, registered 2016-04-14, licence expiry 2029-07-02, status ''Registered and Licensed''","Kenya Accountants and Secretaries National Examinations Board (KASNEB) examinations for the accounting technicians diploma and craft information communication technology","Kenya National Examinations Council (KNEC) examinations for the craft and diploma business programmes"]},"basic_info":{"email":"info@airads.ac.ke","phone":"+254715771316","sources":{"email":["https://www.airads.ac.ke/contact/"],"phone":["https://www.airads.ac.ke/contact/","https://maps.google.com/?cid=10210030319944122343&g_mp=Cidnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLlNlYXJjaFRleHQQAhgEIAA"],"website":["https://www.airads.ac.ke/","https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0088/2016"],"location":["https://www.airads.ac.ke/contact/","https://maps.google.com/?cid=10210030319944122343&g_mp=Cidnb29nbG