insert into "institutions" ("id", "name", "type", "category", "ownership", "operational_status", "website", "email", "phone", "logo_url", "location", "town", "county", "region", "research_data", "validation", "sources", "research_score", "research_status", "created_at", "updated_at", "sync_status", "sync_updated_at", "sync_run_id", "conflict", "verification_status", "verified_at", "verified_by_run", "claimed_by", "claimed_until", "claim_queue", "attempt_count", "last_error", "last_writer", "duplicate_of", "registration_status", "profile_level", "research_note", "research_queued_at", "research_origin", "research_pass", "verification_pass", "conflict_pass", "verification_basis", "estimated_student_count", "has_elearning", "has_distance_learning", "has_teaching_courses", "campuses", "affiliation", "about", "description", "facilities", "accreditations", "courses", "personal_contacts", "health_score", "verified_fields_jsonb", "changelog_jsonb", "last_sync_at", "target_fields", "social_media", "corpus_sources", "institution_sources", "other_sources", "geo", "prefetch_status", "evidence_prefetched_at", "evidence_packaged_at", "prefetch_error") overriding system value values ('3459ec52-ad20-4da9-b75a-ec7ab90f9cf4', 'African International Training Institute', 'TVET', 'TVC', 'private', 'active', 'https://aitec.ac.ke/', 'aitec.mogotio@gmail.com', '0715 244974', 'https://aitec.ac.ke/logo.jpeg', 'Mogotio, 38km north of Nakuru City', 'Equator, Mogotio', 'Baringo County', 'Rift Valley', '{"context":{"about":"African International Training Institute trades as African International Technical College (AITEC), a private technical college at Mogotio in Baringo County, Rift Valley region, Kenya, registered and licensed by the Technical and Vocational Education and Training Authority as TVETA/PRIVATE/TVC/0075/2023. It offers KNEC craft and diploma programmes in health, agriculture, technology and engineering fields plus TVET CDACC Level 4, Level 5 and Level 6 competency-based programmes in cosmetology, caregiving, community health, healthcare support and perioperative theatre technology.","courses":[{"name":"Food and Beverage Production and Service (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Information Communication Technology (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Information Studies (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Nutrition and Dietetics (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Supply Chain Management (Craft)","level":"Certificate","exam_body":"KNEC"},{"name":"Building Technology","level":"Diploma","exam_body":"KNEC"},{"name":"Civil Engineering","level":"Diploma","exam_body":"KNEC"},{"name":"Electrical and Electronics Engineering (Power)","level":"Diploma","exam_body":"KNEC"},{"name":"Fashion Design and Clothing Technology","level":"Diploma","exam_body":"KNEC"},{"name":"Agriculture","level":"Diploma","exam_body":"KNEC"},{"name":"Human Resource Management","level":"Diploma","exam_body":"KNEC"},{"name":"Information Communication Technology (Diploma)","level":"Diploma","exam_body":"KNEC"},{"name":"Social Work and Community Development","level":"Diploma","exam_body":"KNEC"},{"name":"Cosmetology Level 4","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Caregiving Level 4","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Cosmetology Level 5","level":"Certificate","exam_body":"TVET CDACC"},{"name":"Community Health Level 5","level":"Certificate","exam_body":"TVET CDACC"},{"name":"Healthcare Support Services Level 5","level":"Certificate","exam_body":"TVET CDACC"},{"name":"Perioperative Theatre Technology Level 5","level":"Certificate","exam_body":"TVET CDACC"},{"name":"Community Health Level 6","level":"Diploma","exam_body":"TVET CDACC"},{"name":"Perioperative Theatre Technology Level 6","level":"Diploma","exam_body":"TVET CDACC"}],"sources":{"about":"https://aitec.ac.ke/","courses":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0075/2023","description":"https://aitec.ac.ke/","accreditations":"https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0075/2023"},"facilities":[],"description":"African International Training Institute appears in the TVET Authority register as African International Technical College, a private Technical and Vocational College in Baringo County, Rift Valley region, registration number TVETA/PRIVATE/TVC/0075/2023, registered on 31 July 2023 and licensed to 30 July 2028 in ''Registered and Licensed'' status; the college trades as AITEC on its own website and both names are recorded here rather than overwriting either. The regulator''s course table carries twenty-three rows which deduplicate to twenty-one qualifications: five KNEC craft awards, eight KNEC diplomas spanning building, civil, electrical, fashion, agriculture, human resource management, ICT and social work, and TVET CDACC competency-based programmes at Level 4 in cosmetology and caregiving, Level 5 in cosmetology, community health, healthcare support services and perioperative theatre technology, and Level 6 in community health and perioperative theatre technology. Craft awards are mapped to Certificate, diplomas to Diploma, CDACC Level 4 to Artisan and Levels 5 and 6 to Certificate and Diploma respectively. The college''s own site describes it as a technical institution for health, agriculture, technology and engineering, places it at Mogotio 38 kilometres north of Nakuru City with a P.O. Box 12938 Nakuru address, and publishes the telephone lines 0715 244974, 0726 854256, 0741 121599 and 0706 278051 together with the address aitec.mogotio@gmail.com. No student population figure, distance-learning provision or e-learning portal is published, so those remain unverified.","accreditations":["Technical and Vocational Education and Training Authority (TVETA) - status Registered and Licensed, reference TVETA/PRIVATE/TVC/0075/2023, registered 2023-07-31, licence valid to 2028-07-30","Kenya National Exa