y":"rule:auto-sync"},{"field":"has_teaching_courses","action":"gap_sync","new_val":[true,"Food Processing Technology; General Agriculture; Information Communication Technology; Electrical Installation; Motor Vehicle Mechanics; Welding and Fabrication; Hairdressing; Masonry"],"old_val":null,"timestamp":"2026-11-21T10:07:32.877420+00:00","decided_by":"rule:auto-sync","shape_normalized":true},{"field":"about","action":"gap_sync","new_val":"Ahero Vocational Training Center is a public Vocational Training Centre in Ahero, Kisumu County, registered by TVETA under TVETA/PUBLIC/VTC/0143/2016. It began as a church-sponsored youth polytechnic and now delivers artisan, craft and trade-test training in technical trades, ICT, agribusiness and fashion for NITA, KNEC and TVET CDACC examinations.","old_val":null,"timestamp":"2026-11-21T10:07:32.877420+00:00","decided_by":"rule:auto-sync"},{"field":"description","action":"gap_sync","new_val":"Ahero Vocational Training Center is a public technical and vocational institution registered and licensed by TVETA under registration number TVETA/PUBLIC/VTC/0143/2016. It is located at Boya along the Kisumu-Kericho road at Ahero, Kisumu County, in the Nyanza region of Kenya. The centre traces its origins to a youth polytechnic founded in 1968 in the Boya area along the Ahero-Awasi road, and it prepares trainees for practical careers, responsible citizenship and lifelong learning. Its programme list covers artisan and craft courses examined by KNEC and TVET CDACC as well as NITA trade tests in trades such as masonry, welding, plumbing, tailoring, hairdressing and motor vehicle mechanics.","old_val":null,"timestamp":"2026-11-21T10:07:32.877420+00:00","decided_by":"rule:auto-sync"},{"field":"accreditations","action":"gap_sync","new_val":["TVETA registered and licensed, registration TVETA/PUBLIC/VTC/0143/2016"],"old_val":null,"timestamp":"2026-11-21T10:07:32.877420+00:00","decided_by":"rule:auto-sync"},{"field":"courses","action":"gap_sync","new_v