insert into "institutions" ("id", "name", "type", "category", "ownership", "operational_status", "website", "email", "phone", "logo_url", "location", "town", "county", "region", "research_data", "validation", "sources", "research_score", "research_status", "created_at", "updated_at", "sync_status", "sync_updated_at", "sync_run_id", "conflict", "verification_status", "verified_at", "verified_by_run", "claimed_by", "claimed_until", "claim_queue", "attempt_count", "last_error", "last_writer", "duplicate_of", "registration_status", "profile_level", "research_note", "research_queued_at", "research_origin", "research_pass", "verification_pass", "conflict_pass", "verification_basis", "estimated_student_count", "has_elearning", "has_distance_learning", "has_teaching_courses", "campuses", "affiliation", "about", "description", "facilities", "accreditations", "courses", "personal_contacts", "health_score", "verified_fields_jsonb", "changelog_jsonb", "last_sync_at", "target_fields", "social_media", "corpus_sources", "institution_sources", "other_sources", "geo", "prefetch_status", "evidence_prefetched_at", "evidence_packaged_at", "prefetch_error") overriding system value values ('8978f772-91da-4604-8daf-faf0ecd4f3c1', 'Aic - Nairobi Training Centre', 'TVET', 'TVC', 'private', 'active', null, 'nairobitraining@gmail.com', '020 5238491', null, 'Abidha Village, Nairobi', 'Location- Abidha Village, Nairobi', 'Nairobi County', 'Nairobi', '{"context":{"about":"AIC - Nairobi Training Centre is a private Africa Inland Church technical and vocational college in Nairobi County, registered by TVETA under TVETA/PRIVATE/TVC/0145/2017, offering KNEC, NITA, KASNEB and CDACC-accredited courses in electrical trades, catering, hospitality, ICT, business and education from its Jamhuri Estate campus in Woodley, Nairobi.","courses":[{"name":"Electrical Installation","level":"Artisan","exam_body":"KNEC"},{"name":"Food and Beverage","level":"Artisan","exam_body":"KNEC"},{"name":"Catering and Accommodation Management","level":"Diploma","exam_body":"KNEC"},{"name":"Electrical Wireman","level":"Artisan","exam_body":"NITA"},{"name":"Diploma in Early Childhood Teacher Education (DECTE)","level":"Diploma","exam_body":"KNEC"},{"name":"Tailoring","level":"Certificate","exam_body":"NITA"},{"name":"Tie and Dye Techniques","level":"Certificate","exam_body":"NITA"},{"name":"Certified Public Accountants (CPA)","level":"Certificate","exam_body":"KASNEB"},{"name":"Accounting Technicians Diploma (ATD)","level":"Diploma","exam_body":"KASNEB"},{"name":"Catering and Accommodation Operations","level":"Certificate","exam_body":"KNEC"},{"name":"Pastry and Bakery","level":"Certificate","exam_body":"TVET CDACC"}],"sources":{"about":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0145/2017","https://aiccad.org/wp-content/uploads/2026/05/NTC-profilepdf.pdf"],"courses":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0145/2017","https://www.colleges.co.ke/colleges/view-aic-nairobi-training-center","https://education.co.ke/aic-nairobi-training-centre-courses-offered-contacts-application-procedure/"],"description":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0145/2017","https://aiccad.org/wp-content/uploads/2026/05/NTC-profilepdf.pdf","https://education.co.ke/aic-nairobi-training-centre-courses-offered-contacts-application-procedure/","https://www.colleges.co.ke/colleges/view-aic-nairobi-training-center","https://www.facebook.com/p/AIC-Nairobi-Training-Centre-61559482841460/"],"accreditations":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0145/2017"]},"facilities":null,"description":"AIC - Nairobi Training Centre appears in the TVETA register of accredited TVET institutions as a private TVC in Nairobi County, registered on 16 February 2017 under number TVETA/PRIVATE/TVC/0145/2017 and recorded as Registered and Licensed with an expiry date of 28 November 2028. The register table lists four distinct awards after de-duplication: KNEC artisan qualifications in Electrical Installation and in Food and Beverage, a KNEC Diploma in Catering and Accommodation Management, and a NITA Trade Test qualification as an Electrical Wireman. The institution is a training department of the Africa Inland Church, whose parent-body profile places it at Woodley, Jamhuri, Nairobi, with postal address P.O. Box 21882-00505 Nairobi and telephone 020 5238491, and advertises a wider portfolio including ICT, Social Work and Community Development, ECDE and DPTE teacher-training programmes. Third-party programme listings additionally show KASNEB professional courses (CPA and ATD), NITA craft courses in Tailoring and Tie and Dye Techniques, and a CDACC certificate in Pastry and Bakery. The institution''s own Facebook page describes it as ''a private TVET committed to offering quality vocational and educational training for the modern world'' and advertises January intakes in catering, cosmetology, plumbing, electrical, fashion and design, masonry, mechanics, ICT, education, and social work and community development.","accreditations":["Registered and licensed by the Technical and Vocational Education and Training Authority (TVETA) under registration number TVETA/PRIVATE/TVC/0145/2017, registration date 16 February 2017, expiry date 28 November 2028, status Registered and Licensed"]},"basic_info":{"email":"nairobitraining@gmail.com","phone":"+254 20 5238491","sources":{"town":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0145/2017","https://maps.google.com/?cid=4482180947340189421&g_mp=Cidnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLlNlYXJjaFRleHQQAhgEIAA"],"email":["https://aiccad.org/wp-content/uploads/2026/05/NTC-profilepdf.pdf"],"phone":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0145/2017","https://aiccad.org/wp-content/uploads/2026/05/NTC-profilepdf.pdf","https://maps.google.com/?cid=4482180947340189421&g_mp=Cidnb29nbGUubWFwcy5wb