insert into "institutions" ("id", "name", "type", "category", "ownership", "operational_status", "website", "email", "phone", "logo_url", "location", "town", "county", "region", "research_data", "validation", "sources", "research_score", "research_status", "created_at", "updated_at", "sync_status", "sync_updated_at", "sync_run_id", "conflict", "verification_status", "verified_at", "verified_by_run", "claimed_by", "claimed_until", "claim_queue", "attempt_count", "last_error", "last_writer", "duplicate_of", "registration_status", "profile_level", "research_note", "research_queued_at", "research_origin", "research_pass", "verification_pass", "conflict_pass", "verification_basis", "estimated_student_count", "has_elearning", "has_distance_learning", "has_teaching_courses", "campuses", "affiliation", "about", "description", "facilities", "accreditations", "courses", "personal_contacts", "health_score", "verified_fields_jsonb", "changelog_jsonb", "last_sync_at", "target_fields", "social_media", "corpus_sources", "institution_sources", "other_sources", "geo", "prefetch_status", "evidence_prefetched_at", "evidence_packaged_at", "prefetch_error") overriding system value values ('621105bb-3c9e-4f4a-ae0f-054f5b86914b', 'Aic Cheptebo Agricultural & Innovation Centre', 'TVET', 'TVC', 'private', 'active', 'http://www.cheptebo.org/', 'cheptebordc@gmail.com', '0759 931020', 'https://catic.co.ke/img/logo.png', 'Kerio Valley, Keiyo South, Elgeyo Marakwet County', 'Cheptebo', 'Elgeyo Marakwet County', 'Rift Valley', '{"context":{"about":"AIC Cheptebo Agricultural and Innovation Centre is a private TVET institution in the Kerio Valley, Elgeyo Marakwet County, registered by TVETA as TVETA/PRIVATE/TVC/0138/2024. It operates as the Cheptebo Agricultural Training and Innovation Centre (CATIC), a ministry of Africa Inland Church Kenya established in 1986, delivering accredited agricultural courses from Level 3 to Level 5 on a 20-hectare demonstration farm.","courses":[{"name":"Horticulture Level 3","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Poultry Kienyeji Operator Level 3","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Agriculture Extension Level 4","level":"Certificate","exam_body":"TVET CDACC"},{"name":"Horticulture Level 5","level":"Diploma","exam_body":"TVET CDACC"},{"name":"Integrated Pest Management Level 5","level":"Diploma","exam_body":"TVET CDACC"},{"name":"Poultry Breeding Operations Level 5","level":"Diploma","exam_body":"TVET CDACC"},{"name":"Sustainable Agriculture for Rural Development Level 5","level":"Diploma","exam_body":"TVET CDACC"},{"name":"Agripreneurship Level 5","level":"Diploma","exam_body":"TVET CDACC"},{"name":"Apiculture Level 5","level":"Diploma","exam_body":"TVET CDACC"},{"name":"Agriculture and Extension Level 5","level":"Diploma","exam_body":"TVET CDACC"},{"name":"Dairy Farm Attendance Level 3","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Dairy Farm Attendance Level 4","level":"Certificate","exam_body":"TVET CDACC"},{"name":"General Agriculture Level 4","level":"Certificate","exam_body":"TVET CDACC"},{"name":"Poultry Kienyeji Production Level 3","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Poultry Kienyeji Production Level 4","level":"Certificate","exam_body":"TVET CDACC"},{"name":"Sustainable Agriculture for Rural Development Level 3","level":"Artisan","exam_body":"TVET CDACC"},{"name":"Sustainable Agriculture for Rural Development Level 4","level":"Certificate","exam_body":"TVET CDACC"}],"sources":{"about":["https://www.cheptebo.org/","https://catic.co.ke/","https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024"],"courses":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024","https://catic.co.ke/"],"facilities":["https://www.cheptebo.org/","https://www.cheptebo.org/contact.php","https://catic.co.ke/"],"description":["https://www.cheptebo.org/","https://www.cheptebo.org/about-us.php","https://www.cheptebo.org/contact.php","https://catic.co.ke/","https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024"],"accreditations":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024","https://catic.co.ke/"]},"facilities":["20-hectare demonstration and training farm","Training and conference centre with four conference halls","Residential accommodation for 100 guests with kitchen and dining facilities","KEPHIS-certified tree nursery","Fruit processing factory supported by the Government of Japan","Lecture halls and practical training on the demonstration farm"],"description":"AIC Cheptebo Agricultural and Innovation Centre is registered by the TVET Authority as TVETA/PRIVATE/TVC/0138/2024, a private Technical and Vocational College (TVC category) in Elgeyo Marakwet County, Kenya, with the status Registered and Licensed. It operates as the Cheptebo Agricultural Training and Innovation Centre (CATIC), a ministry of Africa Inland Church Kenya established in 1986 and governed by a Board of Management drawn from the church, local leaders and community representatives. CATIC is located in Keiyo South Constituency, Soy North Ward, on the C51 Iten-Kabarnet road near Cheploch Gorge in the southern Kerio Valley, roughly 5 km west of the Chebloch Bridge. The college is purely agricultural, offering fully accredited TVET CDACC programmes from Level 3 to Level 5 in horticulture, dairy farm attendance, poultry production, sustainable agriculture, agriculture extension, agripreneurship, apiculture and integrated pest management, with trainees spending most of their time in hands-on learning on the centre''s 20-hectare demonstration farm. Supporting facilities include a conference centre with four halls and residential accommodation for 100 guests, a KEPHIS-certified tree nursery and a fruit processing factory supported by the Government of Japan, and the college publishes a student portal at students.catic.co.ke and a CDACC results portal at cdacc.catic.co.ke.","accreditations":["TVETA registered and licensed as TVETA/PRIVATE/TVC/0138/2024 (TVC category)","Programmes offered under the TVET CDACC curriculum from Level 3 to Level 5"]},"basic_info":{"email":"cheptebordc@gmail.com","phone":"+254759931020","sources":{"email":["https://www.cheptebo.org/contact.php","https://catic.co.ke/"],"phone":["https://www.cheptebo.org/contact.php","https://catic.co.ke/"],"website":["https://www.cheptebo.org/","https://catic.co.ke/"],"location":["https://www.cheptebo.org/contact.php","https://catic.co.ke/","https://africanspicesafaris.com/tour/cheptebo-rural-development-centre-kerio-valley/"],"logo_url":["https://catic.co.ke/"],"location.town":["https://www.cheptebo.org/contact.php"],"location.county":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024","https://catic.co.ke/"],"location.region":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024"]},"website":"https://www.cheptebo.org/","location":{"town":"Cheptebo","county":"Elgeyo Marakwet County","region":"Rift Valley","location":"Off the C51 Iten-Kabarnet road, approx. 5 km west of Chebloch Bridge, Kerio Valley; P.O. Box 614-30700, Cheptebo"},"logo_url":"https://catic.co.ke/img/logo.png"},"personal_contacts":[{"email":"principal@catic.co.ke","phone":"+254722121897","source":"https://catic.co.ke/","job_title":"Principal, A.I.C Cheptebo Agricultural Training and Innovation Centre (CATIC)","contact_name":"Daniel Chelule","profile_summary":"Mr. Daniel Chelule is the Principal of A.I.C Cheptebo Agricultural Training and Innovation Centre (CATIC), the agricultural college arm of AIC Cheptebo Rural Development Centre, where he leads the accredited TVET agricultural training programmes."},{"email":"joseph.kimeli@cheptebo.org","phone":"+254721343821","source":"https://www.cheptebo.org/about-us.php","job_title":"Centre Director","contact_name":"Joseph Kimeli","profile_summary":"Joseph Kimeli is the Centre Director of AIC Cheptebo Rural Development Centre, directing day-to-day activities across the centre''s sections and serving on the Board of Management."},{"email":"joshua.kipruto@cheptebo.org","phone":"+254729888546","source":"https://www.cheptebo.org/contact.php","job_title":"Deputy Director","contact_name":"Joshua Kipruto","profile_summary":"Joshua Kipruto is the Deputy Director of AIC Cheptebo Rural Development Centre, part of the management team directing the centre''s day-to-day activities."},{"email":"antony.kirwa@cheptebo.org","phone":"+254725650983","source":"https://www.cheptebo.org/contact.php","job_title":"Operations Manager","contact_name":"Antony Kirwa","profile_summary":"Antony Kirwa is the Operations Manager of AIC Cheptebo Rural Development Centre, handling the centre''s day-to-day operations."},{"email":"sally.kimeli@cheptebo.org","phone":"+254721118854","source":"https://www.cheptebo.org/contact.php","job_title":"Conference Centre Manager","contact_name":"Sally Kimeli","profile_summary":"Sally Kimeli is the Conference Centre Manager of AIC Cheptebo Rural Development Centre, managing the training and conference centre facilities."},{"email":"angelyne.mibei@cheptebo.org","phone":"+254712886697","source":"https://www.cheptebo.org/contact.php","job_title":"Accountant","contact_name":"Angelyne Mibei","profile_summary":"Angelyne Mibei is the Accountant of AIC Cheptebo Rural Development Centre, handling the centre''s finances."},{"email":"daniel.tarus@cheptebo.org","phone":"+254795396689","source":"https://www.cheptebo.org/contact.php","job_title":"Farm Manager","contact_name":"Daniel Tarus","profile_summary":"Daniel Tarus is the Farm Manager of AIC Cheptebo Rural Development Centre, managing the 20-hectare demonstration and training farm."},{"email":"obadiah.kigen@cheptebo.org","phone":"+254722296370","source":"https://www.cheptebo.org/contact.php","job_title":"Customer Relations Officer","contact_name":"Obadiah Kigen","profile_summary":"Obadiah Kigen is the Customer Relations Officer of AIC Cheptebo Rural Development Centre, handling client and visitor relations."}],"institution_profile":{"type":"TVET","sources":{"type":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024"],"campuses":["https://www.cheptebo.org/","https://catic.co.ke/"],"category":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024"],"ownership":["https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024"],"affiliation":["https://www.cheptebo.org/about-us.php","https://catic.co.ke/"],"has_elearning":["https://catic.co.ke/"],"has_teaching_courses":["https://catic.co.ke/","https://www.tveta.go.ke/institution-details/?details=TVETA/PRIVATE/TVC/0138/2024"],"has_distance_learning":["https://catic.co.ke/"]},"campuses":["Cheptebo Agricultural Training and Innovation Centre (CATIC) - Keiyo South, Soy North Ward, on the C51 Iten-Kabarnet road near Cheploch Gorge, Kerio Valley"],"category":"TVC","ownership":"private","affiliation":["Africa Inland Church Kenya"],"has_elearning":["implied","CATIC publishes a Student Portal at https://students.catic.co.ke/student_login and a CDACC results portal at https://cdacc.catic.co.ke/, but no LMS/e-learning platform URL (moodle, lms, e-learning, canvas) is published, so this is a generic student portal, not verified e-learning."],"has_teaching_courses":[true,["Horticulture Level 3","Dairy Farm Attendance Level 4","General Agriculture Level 4","Agriculture and Extension Level 5","Sustainable Agriculture for Rural Development Level 5","Apiculture Level 5"]],"has_distance_learning":["none","All CATIC programmes are delivered in person through lecture-hall instruction and practical work on the 20-hectare demonstration farm; no distance-learning or ODeL provision is published on catic.co.ke or cheptebo.org."]}}', '{"field_verdicts":{"town":{"status":"confirmed","verdict":"confirmed","rationale":"town (''Cheptebo'') corroborated in cached evidence.","source_url":"https://maps.